using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryAuthorityScopeTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static void Send(WorldSession s,NewMilitaryAction action){var r=s.DecideNewMilitary(new(new("request:authority-scope/"+s.Revision+"/"+action),action),s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static (WorldSession Session,MilitaryAuthorityProof Proof) Permission(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,3);var w=s.DiagnosticSnapshot();var e=w.NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.Permission);var source=NewGameMilitaryAuthority.Resolve(w,w.NewMilitary.Terms.Principal,s.PlayerControl,w.NewMilitary.Terms.Owner,w.NewMilitary.Terms.Site)!;Assert.NotNull(source);return(s,new(w.NewMilitary.Terms.Case,e.Effect,e.At,e.Revision,source with{At=e.At,Revision=e.Revision}));}
 static (WorldSession Session,MilitaryAuthorityProof Proof,MilitaryScopedGrant Grant) Pickup(){var (s,p)=Permission();At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);return(s,p,Assert.Single(NewGameMilitary.BuildAuthorityScopes(s.DiagnosticSnapshot(),[p])));}
 [Fact]public void PermissionAloneCreatesNoCommandUntilActualPickup(){var(s,p)=Permission();var w=s.DiagnosticSnapshot();Assert.Empty(NewGameMilitary.BuildAuthorityScopes(w,[p]));At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);w=s.DiagnosticSnapshot();var g=Assert.Single(NewGameMilitary.BuildAuthorityScopes(w,[p]));Assert.Equal(w.NewMilitary!.Terms.Owner,g.Owner);Assert.Equal(w.NewMilitary.Terms.Principal,g.Mandate.Principal);Assert.Equal(s.PlayerControl,g.Mandate.Agent);Assert.All(w.Units,u=>Assert.Equal(g.Owner,u.Organization));Assert.True(NewGameMilitary.ScopedAuthorityAllows(g,g.Case,s.PlayerControl,g.Mandate.Army,g.Mandate.Units[1],RegionalAction.Move,s.Seconds,s.Revision));}
 [Theory][InlineData("actor")][InlineData("army")][InlineData("unit")][InlineData("case")][InlineData("combat")]
 public void PlacementGrantDoesNotAuthorizeAnotherActorArmyUnitCaseOrHistoricalAttack(string variant){var(s,_,g)=Pickup();var actor=s.PlayerControl;var army=g.Mandate.Army;var unit=g.Mandate.Units[0];var militaryCase=g.Case;var action=RegionalAction.Move;if(variant=="actor")actor=g.Mandate.Principal;if(variant=="army")army=new("army:other");if(variant=="unit")unit=new("unit:other");if(variant=="case")militaryCase=new("request:other-case");if(variant=="combat")action=RegionalAction.Engage;Assert.False(NewGameMilitary.ScopedAuthorityAllows(g,militaryCase,actor,army,unit,action,s.Seconds,s.Revision));}
 [Fact]public void ForgedAuthoritySourceCannotMintACaseGrant(){var(s,p,_)=Pickup();var w=s.DiagnosticSnapshot();string hash=ContractJson.CanonicalHash(w);Assert.Throws<InvalidDataException>(()=>NewGameMilitary.BuildAuthorityScopes(w,[p with{Source=p.Source with{Owner=new("org:other")}}]));Assert.Throws<InvalidDataException>(()=>NewGameMilitary.BuildAuthorityScopes(w,[p with{Case=new("request:other-case")} ]));Assert.Equal(hash,ContractJson.CanonicalHash(w));}
 [Fact]public void ActualReturnClosesOnlyTheCaseGrantAtItsCommittedRevision(){var(s,p,g)=Pickup();Send(s,NewMilitaryAction.Report);At(s,s.Seconds+1);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+1);var w=s.DiagnosticSnapshot();var end=w.NewMilitary!.Events.Single(e=>e.Effect==MilitaryEffect.Returned);var closed=Assert.Single(NewGameMilitary.BuildAuthorityScopes(w,[p]));Assert.Equal(end.At,closed.Mandate.Until);Assert.Equal(end.Revision,closed.UntilRevision);Assert.True(NewGameMilitary.ScopedAuthorityAllows(closed,g.Case,s.PlayerControl,g.Mandate.Army,g.Mandate.Units[0],RegionalAction.Hold,end.At,end.Revision-1));Assert.False(NewGameMilitary.ScopedAuthorityAllows(closed,g.Case,s.PlayerControl,g.Mandate.Army,g.Mandate.Units[0],RegionalAction.Hold,end.At,end.Revision));Assert.All(w.Units,u=>Assert.Equal(g.Owner,u.Organization));}
 [Theory][InlineData("entry")][InlineData("source")][InlineData("duplicate")]public void MalformedOrDuplicateAuthorityProofIsRejectedWithoutWorldMutation(string variant){var(s,p,_)=Pickup();var w=s.DiagnosticSnapshot();var proofs=variant switch{"entry"=>new MilitaryAuthorityProof[]{null!},"source"=>new[]{p with{Source=null!}},_=>new[]{p,p}};string hash=ContractJson.CanonicalHash(w);Assert.Throws<InvalidDataException>(()=>NewGameMilitary.BuildAuthorityScopes(w,proofs));Assert.Equal(hash,ContractJson.CanonicalHash(w));}
}
